fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // We assume 1 <= k < list.len()
    let n = list.len();
    let remove_idx = k - 1; // convert to 0-based index

    // Prepare a new vector with one fewer element
    let mut new_list = Vec::with_capacity(n - 1);
    
    // Take all elements before the removal index
    new_list.extend_from_slice(&list[..remove_idx]);
    // Take all elements after the removal index
    new_list.extend_from_slice(&list[remove_idx + 1..]);
    
    new_list
}

